public final class OrdersModule {
    private final JdbcTemplate jdbc;
    public OrdersModule(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    public List<Map<String, Object>> overdue(LocalDate asOf) {   // record set out
        return jdbc.queryForList("select id, due, total from orders where due < ?", asOf);
    }

    public int flagOverdue(LocalDate asOf) {                     // set-oriented write
        return jdbc.update("update orders set flagged = true where due < ?", asOf);
    }
}
